r=dict(primary_membership_sha256=hashlib.sha256((O/'nearest_membership.parquet').read_bytes()).hexdigest(),n_rows=len(p),n_zero_urban2010_candidates=len(zero),candidate_ids=zero.id.tolist(),new_geometry_centers=len(ci),changed_settlements=int(changed.sum()),changed_own_zero_centers=int(imp.id.isin(zero.id).sum()),changed_other_settlements=int((~imp.id.isin(zero.id)).sum()),changed_observed_population={str(y):float(p.loc[changed,f'population_{y}'].sum()) for y in [2002,2010,2021]},new_zero_mass_center_basins=len(basins),new_basins_with_zero_total2010=int(basins.population_2010.eq(0).sum()),new_basins_with_zero_total2021=int(basins.population_2021.eq(0).sum()),zero_urban_cases_zero2021=int(zero.population_2021.eq(0).sum()),huff_policy='unchanged: no artificial positive mass assigned to zeros',interpretation='alternative geometry; demographic mass zero does not prove no service function',primary_model_unchanged=True)
